#include <algorithm>
#include <fstream>
#include <vector>
int main() {
    std::ifstream in("homework.in");
    std::ofstream out("homework.out");
    int n;
    in >> n;
    std::vector<int> score(n), minimum(n + 1, 10001);
    std::vector<long long> sum(n + 1, 0);
    for (int &value : score) in >> value;
    for (int i = n - 1; i >= 0; --i) {
        sum[i] = sum[i + 1] + score[i];
        minimum[i] = std::min(minimum[i + 1], score[i]);
    }
    long long bestNumerator = -1, bestDenominator = 1;
    std::vector<int> answers;
    for (int k = 1; k <= n - 2; ++k) {
        const long long numerator = sum[k] - minimum[k];
        const long long denominator = n - k - 1;
        const long long left = numerator * bestDenominator;
        const long long right = bestNumerator * denominator;
        if (left > right) {
            bestNumerator = numerator;
            bestDenominator = denominator;
            answers.clear();
            answers.push_back(k);
        } else if (left == right) answers.push_back(k);
    }
    for (int k : answers) out << k << '\n';
}
