#include <algorithm>
#include <fstream>
#include <map>
#include <vector>
struct Record {
    int day, cow;
    long long change;
};
int main() {
    std::ifstream in("measurement.in");
    std::ofstream out("measurement.out");
    int n;
    long long baseline;
    in >> n >> baseline;
    std::vector<Record> records(n);
    std::map<int, long long> milk;
    for (auto &record : records) {
        in >> record.day >> record.cow >> record.change;
        milk.emplace(record.cow, baseline);
    }
    std::sort(records.begin(), records.end(), [](const Record &a, const Record &b) {
        return a.day < b.day;
    });
    // One fixed marker represents the nonempty unchanged herd at baseline.
    // It preserves display-set equality, not the actual number of these cows.
    std::map<long long, int> frequency;
    frequency[baseline] = static_cast<int>(milk.size()) + 1;
    int answer = 0;
    for (const auto &record : records) {
        const long long oldValue = milk[record.cow];
        const long long oldMaximum = frequency.rbegin()->first;
        const bool oldLeader = oldValue == oldMaximum;
        const int oldLeaderCount = frequency.rbegin()->second;
        if (--frequency[oldValue] == 0) frequency.erase(oldValue);
        const long long newValue = oldValue + record.change;
        milk[record.cow] = newValue;
        ++frequency[newValue];
        const bool newLeader = newValue == frequency.rbegin()->first;
        const int newLeaderCount = frequency.rbegin()->second;
        if (oldLeader != newLeader ||
            (oldLeader && newLeader && (oldLeaderCount != 1 || newLeaderCount != 1)))
            ++answer;
    }
    out << answer << '\n';
}
