#include <fstream>
#include <queue>
#include <vector>
int main() {
    std::ifstream in("shuffle.in");
    std::ofstream out("shuffle.out");
    int n;
    in >> n;
    std::vector<int> destination(n), indegree(n, 0);
    for (int &position : destination) {
        in >> position;
        --position;
        ++indegree[position];
    }
    std::queue<int> empty;
    for (int i = 0; i < n; ++i)
        if (indegree[i] == 0) empty.push(i);
    int remaining = n;
    while (!empty.empty()) {
        const int position = empty.front();
        empty.pop();
        --remaining;
        const int next = destination[position];
        if (--indegree[next] == 0) empty.push(next);
    }
    out << remaining << '\n';
}
